    const bars=days.map((d,i)=>{const bw=Math.max(3,step*.28),x=L+i*step+step*.18,h1=exp[i]/max*ih,h2=inc[i]/max*ih,bh1=exp[i]?Math.max(4,h1):0,bh2=inc[i]?Math.max(4,h2):0;return `<rect class="chart-day-hit" x="${L+i*step}" y="${T}" width="${step}" height="${ih}" fill="transparent" data-chart-day="${d}" data-expense="${exp[i]}" data-income="${inc[i]}" tabindex="0" role="button" aria-label="${d}: expenses ${money(exp[i])}, income ${money(inc[i])}"/><rect x="${x}" y="${T+ih-bh1}" width="${bw}" height="${bh1}" rx="2" fill="#ff765e" data-chart-bar="expense" data-day="${d}" data-amount="${exp[i]}" tabindex="${exp[i]?'0':'-1'}" aria-label="${d} spending ${money(exp[i])}"/><rect x="${x+bw+2}" y="${T+ih-bh2}" width="${bw}" height="${bh2}" rx="2" fill="#a3ff12" data-chart-bar="income" data-day="${d}" data-amount="${inc[i]}" tabindex="${inc[i]?'0':'-1'}" aria-label="${d} income ${money(inc[i])}"/>${i%Math.ceil(days.length/7)===0?`<text x="${x}" y="${H-4}" font-size="9" font-family="DM Mono">${d}</text>`:''}`}).join('');
