  function reports(){let n=monthItems().length;return `${head('Your records, ready when you are.',`Build a clean monthly statement from your transactions.`,false)}<div class="reports-grid"><div class="export-box"><div class="eyebrow" style="color:#a3ff12">REPORT BUILDER</div><h2>Take your numbers with you.</h2><p>Download a formatted workbook with a monthly summary, every transaction, category totals, and daily cash flow. Your records stay on this device.</p><div class="export-options"><label>Report period<select id="reportPeriod"><option value="selected">Selected month</option><option value="previous">Previous month</option><option value="custom">Custom date range</option><option value="year">Entire year</option></select></label><label id="customDates" style="display:none">Start and end dates<span style="display:flex;gap:8px"><input type="date" id="dateStart"><input type="date" id="dateEnd"></span></label><label id="yearWrap" style="display:none">Year<input type="number" id="reportYear" value="${picked().slice(0,4)}" min="2000" max="2100"></label><div style="font-size:11px;color:#adb5ad" id="reportCount">${n} transactions in selected month</div></div><button class="button-primary" data-export="xlsx">↓ Download Excel workbook</button> <button class="button-secondary" data-export="csv" style="margin-left:8px">Download CSV</button></div><div class="report-sheets"><div class="panel-head" style="margin:3px 0 1px"><div><div class="panel-title">Inside the workbook</div><div class="panel-subtitle">Four clear, filterable sheets</div></div></div>${[['▦','Monthly Summary','Income, expenses, savings, and category totals'],['↔','All Transactions','Every record with the details you entered'],['◉','Category Breakdown','Totals, counts, and share of spending'],['▥','Daily Summary','Income, expenses, and net by date']].map(x=>`<div class="sheet-row"><span class="sheet-icon">${x[0]}</span><div><b>${x[1]}</b><small>${x[2]}</small></div></div>`).join('')}</div></div>`}
  function settings(){return `${head('Profile settings','Manage your profile and account security.',false)}<div class="settings-grid"><section class="panel settings-panel"><div class="panel-head"><div><div class="panel-title">Your profile</div><div class="panel-subtitle">Your name and photo appear in your Ledgerline account.</div></div></div><div class="profile-editor"><span class="avatar profile-photo-preview" id="profilePhotoPreview">${esc((currentUser?.displayName||currentUser?.email||'U').trim().charAt(0).toUpperCase())}</span><label class="button-secondary upload-photo-label" for="profilePhotoInput">Choose photo</label><input id="profilePhotoInput" type="file" accept="image/*" hidden><small>JPG or PNG · saved to your private profile</small></div><label class="field profile-name-field"><span>Profile name</span><input id="profileNameInput" maxlength="80" value="${esc(currentUser?.displayName||'')}" placeholder="Your name"></label><button class="button-primary" id="saveProfileName" type="button">Save profile</button><div class="setting-action"><div><b>Change password</b><small>We’ll email you a secure password reset link.</small></div><button class="button-secondary" id="changePassword">Send reset email</button></div><div class="setting-action"><div><b>Sign out</b><small>Sign out of Ledgerline on this device.</small></div><button class="button-secondary" id="settingsSignOut">Sign out</button></div></section><section class="panel settings-panel"><div class="panel-head"><div><div class="panel-title">App preferences</div><div class="panel-subtitle">These preferences sync with your account.</div></div></div><label class="setting-row"><span><b>Theme</b><small>Choose light or dark appearance</small></span><select id="settingTheme"><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option></select></label><label class="setting-row"><span><b>Text size</b><small>Adjust the interface text size</small></span><select id="settingFont"><option value="small" ${state.fontSize==='small'?'selected':''}>Small</option><option value="medium" ${(!state.fontSize||state.fontSize==='medium')?'selected':''}>Medium</option><option value="large" ${state.fontSize==='large'?'selected':''}>Large</option></select></label><label class="setting-row"><span><b>Default payment method</b><small>Preselected for new transactions</small></span><select id="settingPayment">${['UPI','Card','Cash','Bank transfer','Other'].map(x=>`<option ${x===(state.defaultPayment||'UPI')?'selected':''}>${x}</option>`).join('')}</select></label><label class="setting-row"><span><b>Compact transaction list</b><small>Show more transactions on screen</small></span><input id="settingCompact" type="checkbox" ${state.compactMode?'checked':''}></label><div class="setting-action"><div><b>Your data</b><small>Your records are private to your Firebase account.</small></div><span class="account-status">Cloud sync on</span></div></section></div>`}  function authError(error){if(error?.code==='auth/unauthorized-domain')return `Google sign-in was blocked because “${location.hostname}” is not authorized in Firebase. The launcher now uses localhost; close the old site and reopen Start Ledgerline.bat. If this still appears, add “${location.hostname}” at Firebase Console → Authentication → Settings → Authorized domains.`;const messages={'auth/invalid-credential':'Email or password is incorrect.','auth/email-already-in-use':'An account already uses that email. Sign in instead.','auth/weak-password':'Choose a password with at least 6 characters.','auth/invalid-email':'Enter a valid email address.','auth/popup-closed-by-user':'Google sign-in was closed before it finished.','auth/too-many-requests':'Too many attempts. Wait a moment and try again.','auth/network-request-failed':'Could not connect. Check your internet connection.'};return messages[error?.code]||error?.message||'Something went wrong. Please try again.'}
  function renderFirebaseSetup(){document.body.classList.add('auth-mode');app.innerHTML=`<section class="auth-card"><a class="brand auth-brand" href="#"><img class="brand-mark" src="./ledgerline-mark.svg" alt=""><span>ledger<span class="brand-dot">line</span></span></a><div class="eyebrow">ONE ACCOUNT · ANY DEVICE</div><h1>Connect your Firebase project</h1><p>Authentication and sync are ready to use. Add your Firebase web app settings to <code>.env.local</code>, enable Email/Password and Google sign-in, then restart the site.</p><ol><li>Create or open a project in Firebase Console.</li><li>Register a Web app and copy its config values.</li><li>Enable Authentication providers and create a Firestore database.</li></ol><div class="auth-help">Setup steps are in <b>README.md</b>. This app stays locked until Firebase is configured; it will not pretend local-only login syncs across devices.</div></section>`}
  function renderAuth(error=''){document.body.classList.add('auth-mode');const signup=authMode==='signup';app.innerHTML=`<section class="auth-card"><a class="brand auth-brand" href="#"><img class="brand-mark" src="./ledgerline-mark.svg" alt=""><span>ledger<span class="brand-dot">line</span></span></a><div class="eyebrow">YOUR FINANCES, IN SYNC</div><h1>${signup?'Create your account':'Welcome back'}</h1><p>${signup?'Your transactions follow you across your devices.':'Sign in to see your synced transactions and budgets.'}</p>${error?`<div class="auth-error" role="alert">${esc(error)}</div>`:''}<button class="google-button" id="googleSignIn" type="button"><span class="google-g">G</span>Continue with Google</button><div class="auth-divider"><span>or use email</span></div><form id="authForm" class="auth-form">${signup?'<label class="field"><span>Your name</span><input name="name" autocomplete="name" maxlength="80" required placeholder="Name"></label>':''}<label class="field"><span>Email address</span><input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label class="field"><span>Password</span><input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="6" required placeholder="At least 6 characters"></label>${signup?'':'<button type="button" class="forgot-link" id="forgotPassword">Forgot password?</button>'}<button class="button-primary auth-submit" type="submit">${signup?'Create account':'Sign in'}</button></form><p class="auth-switch">${signup?'Already have an account?':'New to Ledgerline?'} <button type="button" id="switchAuth">${signup?'Sign in':'Create account'}</button></p><p class="auth-privacy">Your data is stored in your Firebase account and is private to you.</p></section>`;
    document.getElementById('switchAuth').onclick=()=>{authMode=signup?'login':'signup';renderAuth()};
    document.getElementById('googleSignIn').onclick=async()=>{try{await signInGoogle()}catch(e){renderAuth(authError(e))}};
    document.getElementById('authForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.currentTarget),email=String(form.get('email')).trim(),password=String(form.get('password'));try{if(signup)await createEmailAccount(String(form.get('name')||''),email,password);else await signInEmail(email,password)}catch(error){renderAuth(authError(error))}};
    const forgot=document.getElementById('forgotPassword');if(forgot)forgot.onclick=async()=>{const email=document.querySelector('[name="email"]').value.trim();if(!email)return renderAuth('Enter your email address first, then choose forgot password.');try{await resetPassword(email);renderAuth('Password reset email sent. Check your inbox.')}catch(e){renderAuth(authError(e))}};
  }
  function renderCloudLoading(){document.body.classList.add('auth-mode');app.innerHTML='<section class="auth-card auth-loading"><img class="loading-mark" src="./ledgerline-mark.svg" alt=""><div class="loading-spinner" aria-hidden="true"></div><h1>Loading your account</h1><p id="cloudLoadingMessage" role="status">Connecting your saved transactions and budgets…</p><div class="loading-recovery" id="loadingRecovery" hidden><button class="button-secondary" id="loadingRetry" type="button">Retry connection</button><button class="button-secondary" id="loadingSignOut" type="button">Sign out</button></div></section>';document.getElementById('loadingRetry').onclick=()=>beginCloudSync(currentUser);document.getElementById('loadingSignOut').onclick=async()=>{clearTimeout(cloudLoadTimer);if(unsubscribeCloud){unsubscribeCloud();unsubscribeCloud=null}await signOutNow()};clearTimeout(cloudLoadTimer);cloudLoadTimer=setTimeout(()=>{const msg=document.getElementById('cloudLoadingMessage'),recovery=document.getElementById('loadingRecovery');if(msg)msg.textContent='This is taking longer than expected. Check your connection and confirm your Firestore database and rules are ready.';if(recovery)recovery.hidden=false},15000)}
  function renderCloudFailure(error){clearTimeout(cloudLoadTimer);renderCloudLoading();clearTimeout(cloudLoadTimer);const msg=document.getElementById('cloudLoadingMessage'),recovery=document.getElementById('loadingRecovery'),spinner=document.querySelector('.loading-spinner');if(msg)msg.textContent=`Could not connect to your account: ${authError(error)}`;if(recovery)recovery.hidden=false;if(spinner)spinner.hidden=true}
  function paintAvatar(element,name,photo=''){if(!element)return;element.replaceChildren();if(photo){const image=document.createElement('img');image.src=photo;image.alt='';element.append(image)}else element.textContent=(name||'U').trim().charAt(0).toUpperCase()}
  function applyCloudData(data){const photoKey=`${KEY}:profile-photo:${currentUser.uid}`,profilePhoto=data.profilePhoto||localStorage.getItem(photoKey)||'';if(data.profilePhoto)localStorage.setItem(photoKey,data.profilePhoto);state={...state,...data,transactions:data.transactions||[],budgets:data.budgets||{},theme:data.theme||'light',fontSize:data.fontSize||'medium',defaultPayment:data.defaultPayment||'UPI',compactMode:Boolean(data.compactMode),profilePhoto};localStorage.setItem(KEY,JSON.stringify(state));document.documentElement.classList.toggle('dark',state.theme==='dark');document.documentElement.dataset.fontSize=state.fontSize;document.documentElement.classList.toggle('compact-mode',state.compactMode);document.body.classList.remove('auth-mode');render()}
  function offerLocalImport(localData){document.body.classList.add('auth-mode');app.innerHTML=`<section class="auth-card"><div class="eyebrow">THIS DEVICE</div><h1>Bring your existing records?</h1><p>Your account is ready. This browser has ${localData.transactions.length} transaction${localData.transactions.length===1?'':'s'} and ${Object.keys(localData.budgets||{}).length?'saved budget settings':'no saved budgets'}. Choose whether to copy them into your private Firebase account.</p><div class="auth-actions"><button class="button-secondary" id="skipImport">Start with cloud account</button><button class="button-primary" id="importLocal">Import this device</button></div><p class="auth-privacy">This sends the records shown above to the Firebase project configured for this app.</p></section>`;document.getElementById('skipImport').onclick=()=>applyCloudData(cloudState);document.getElementById('importLocal').onclick=async()=>{const button=document.getElementById('importLocal');button.disabled=true;try{await syncUserData(currentUser.uid,localData,cloudState);cloudState=structuredClone(localData);applyCloudData(cloudState)}catch(e){button.disabled=false;app.querySelector('.auth-card').insertAdjacentHTML('beforeend',`<div class="auth-error">${esc(authError(e))}</div>`)}}}
  function beginCloudSync(user){clearTimeout(cloudLoadTimer);if(unsubscribeCloud){unsubscribeCloud();unsubscribeCloud=null}currentUser=user;cloudReady=false;cloudState={transactions:[],budgets:{},theme:'light'};if(!user){renderAuth();return}renderCloudLoading();const localData=structuredClone(state);unsubscribeCloud=watchUserData(user.uid,data=>{if(!cloudReady){clearTimeout(cloudLoadTimer);cloudReady=true;cloudState=structuredClone(data);const cloudEmpty=!data.transactions.length&&!Object.keys(data.budgets).length;if(cloudEmpty&&(localData.transactions.length||Object.keys(localData.budgets).length>0)){offerLocalImport(localData);return}}cloudState=structuredClone(data);applyCloudData(data)},error=>{console.error(error);renderCloudFailure(error)})}
  function startAuth(){if(!firebaseEnabled){renderFirebaseSetup();return}watchAuth(beginCloudSync)}
  function render(){if(!firebaseEnabled){renderFirebaseSetup();return}if(!currentUser){renderAuth();return}if(!cloudReady){renderCloudLoading();return}document.body.classList.remove('auth-mode');const name=currentUser.displayName||currentUser.email||'Your account',photo=state.profilePhoto||'',profile=document.getElementById('profileBtn');profile.querySelector('.profile-copy b').textContent=name;profile.querySelector('.profile-copy small').textContent=currentUser.email||'Signed in';document.getElementById('menuProfileName').textContent=currentUser.displayName||'Your account';document.getElementById('menuProfileEmail').textContent=currentUser.email||'';paintAvatar(profile.querySelector('.avatar'),name,photo);paintAvatar(document.querySelector('.top-avatar'),name,photo);paintAvatar(document.querySelector('.menu-avatar'),name,photo);document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));app.innerHTML=({dashboard,transactions,budgets,analytics:insights,reports,settings})[view]();if(view==='settings')paintAvatar(document.getElementById('profilePhotoPreview'),name,photo);wire()}
  function wire(){app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));app.querySelectorAll('[data-action="add"]').forEach(b=>b.onclick=()=>openModal());app.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openModal(state.transactions.find(x=>x.id===b.dataset.edit)));app.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeTx(b.dataset.delete));app.querySelectorAll('[data-budget]').forEach(b=>b.onclick=()=>budgetModal(b.dataset.budget));app.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportReport(b.dataset.export));let si=document.getElementById('searchInput');if(si)si.oninput=()=>{query=si.value;let pos=si.selectionStart;render();let next=document.getElementById('searchInput');next.focus();next.setSelectionRange(pos,pos)};let tf=document.getElementById('typeFilter');if(tf)tf.onchange=()=>{filterType=tf.value;render()};let cf=document.getElementById('categoryFilter');if(cf)cf.onchange=()=>{filterCategory=cf.value;render()};let rf=document.getElementById('resetFilters');if(rf)rf.onclick=()=>{query='';filterType=filterCategory='all';render()};let rp=document.getElementById('reportPeriod');if(rp)rp.onchange=()=>{document.getElementById('customDates').style.display=rp.value==='custom'?'grid':'none';document.getElementById('yearWrap').style.display=rp.value==='year'?'grid':'none';updateReportCount()};    ['dateStart','dateEnd','reportYear'].forEach(id=>{let el=document.getElementById(id);if(el)el.onchange=updateReportCount});
    const profileNameSave=document.getElementById('saveProfileName');if(profileNameSave)profileNameSave.onclick=async()=>{const name=document.getElementById('profileNameInput').value.trim();if(!name)return toast('Enter a profile name.');profileNameSave.disabled=true;try{await updateAccountName(name);render();toast('Profile name updated')}catch(error){toast(authError(error));profileNameSave.disabled=false}};const photoInput=document.getElementById('profilePhotoInput');if(photoInput)photoInput.onchange=()=>{const file=photoInput.files?.[0];if(!file)return;if(file.size>8*1024*1024)return toast('Choose an image smaller than 8 MB.');const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas'),size=256;canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d'),scale=Math.max(size/image.width,size/image.height),width=image.width*scale,height=image.height*scale;ctx.drawImage(image,(size-width)/2,(size-height)/2,width,height);state.profilePhoto=canvas.toDataURL('image/jpeg',.78);localStorage.setItem(`${KEY}:profile-photo:${currentUser.uid}`,state.profilePhoto);const pendingSave=save();render();pendingSave.then(ok=>{if(ok)toast('Profile photo saved to your account')})};image.onerror=()=>toast('That image could not be opened. Choose another photo.');image.src=String(reader.result)};reader.onerror=()=>toast('Could not read that photo. Try another one.');reader.readAsDataURL(file)};    const saveSetting=(key,value)=>{state[key]=value;if(key==='theme')document.documentElement.classList.toggle('dark',value==='dark');if(key==='fontSize')document.documentElement.dataset.fontSize=value;if(key==='compactMode')document.documentElement.classList.toggle('compact-mode',value);save();render()};const themeSetting=document.getElementById('settingTheme');if(themeSetting)themeSetting.onchange=()=>saveSetting('theme',themeSetting.value);const fontSetting=document.getElementById('settingFont');if(fontSetting)fontSetting.onchange=()=>saveSetting('fontSize',fontSetting.value);const paySetting=document.getElementById('settingPayment');if(paySetting)paySetting.onchange=()=>saveSetting('defaultPayment',paySetting.value);const compactSetting=document.getElementById('settingCompact');if(compactSetting)compactSetting.onchange=()=>saveSetting('compactMode',compactSetting.checked);const changePassword=document.getElementById('changePassword');if(changePassword)changePassword.onclick=async()=>{try{await resetPassword(currentUser.email);toast('Password reset email sent. Check your inbox.')}catch(error){toast(authError(error))}};const settingsSignOut=document.getElementById('settingsSignOut');if(settingsSignOut)settingsSignOut.onclick=async()=>{await signOutNow()};
    app.querySelectorAll('.chart-wrap').forEach(w=>{
      const tip=w.querySelector('.chart-tooltip');
      const show=(target,clientX,clientY)=>{const day=target.dataset.chartDay||target.dataset.day,expense=target.dataset.chartDay?Number(target.dataset.expense):target.dataset.chartBar==='expense'?Number(target.dataset.amount):null,income=target.dataset.chartDay?Number(target.dataset.income):target.dataset.chartBar==='income'?Number(target.dataset.amount):null;const date=new Date(`${picked()}-${day}T12:00:00`).toLocaleDateString('en-IN',{day:'numeric',month:'short'});tip.innerHTML=`<b>${date}</b>${expense===null?'':`<span><i class="legend-dot" style="background:#ff765e"></i>Spent ${money(expense)}</span>`}${income===null?'':`<span><i class="legend-dot" style="background:#a3ff12"></i>Income ${money(income)}</span>`}`;tip.hidden=false;const r=w.getBoundingClientRect();tip.style.left=`${Math.max(4,Math.min(r.width-155,clientX-r.left+12))}px`;tip.style.top=`${Math.max(4,Math.min(r.height-65,clientY-r.top-54))}px`};
      w.addEventListener('pointerover',e=>{const target=e.target.closest('[data-chart-day],[data-chart-bar]');if(target)show(target,e.clientX,e.clientY)});
      w.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'){const target=e.target.closest('[data-chart-day],[data-chart-bar]');if(target)show(target,e.clientX,e.clientY)}});
      w.addEventListener('pointerout',e=>{if(e.pointerType!=='touch'&&!e.relatedTarget?.closest?.('[data-chart-day],[data-chart-bar]'))tip.hidden=true});
      w.addEventListener('click',e=>{const target=e.target.closest('[data-chart-day],[data-chart-bar]');if(!target)return;const r=target.getBoundingClientRect();show(target,r.left+r.width/2,r.top)});
      w.addEventListener('focusin',e=>{const target=e.target.closest('[data-chart-day],[data-chart-bar]');if(target){const r=target.getBoundingClientRect();show(target,r.left+r.width/2,r.top)}});
      w.addEventListener('focusout',()=>{setTimeout(()=>{if(!w.contains(document.activeElement))tip.hidden=true},80)});
    });
  }
  function openModal(tx,kind){editing=tx||null;draftType=kind||tx?.type||'expense';const c=tx?.category||'Food';document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><form class="modal" id="txForm"><div class="modal-head"><h2>${tx?'Edit transaction':'Add a transaction'}</h2><button type="button" class="modal-close" id="closeModal" aria-label="Close">×</button></div><div class="type-switch"><button type="button" data-kind="expense" class="${draftType==='expense'?'selected':''}">Expense</button><button type="button" data-kind="income" class="${draftType==='income'?'selected':''}">Income</button></div><div class="form-grid" style="margin-top:13px"><div class="field"><label for="amount">Amount (₹)</label><input id="amount" type="number" min="0.01" step="0.01" required placeholder="0.00" value="${tx?tx.amount:''}"></div><div class="field"><label for="category">Category</label><select id="category">${Object.keys(categories).filter(k=>draftType==='expense'?!['Salary','Freelance','Business','Investment','Gift'].includes(k):['Salary','Freelance','Business','Investment','Gift','Other'].includes(k)).map(k=>`<option ${k===c?'selected':''}>${k}</option>`).join('')}</select></div><div class="field full"><label for="description">Description</label><input id="description" required maxlength="100" placeholder="What was it for?" value="${esc(tx?.description||'')}"></div><div class="field"><label for="date">Date</label><input id="date" type="date" required value="${tx?.date||today()}"></div><div class="field"><label for="payment">Payment method</label><select id="payment">${['UPI','Card','Cash','Bank transfer','Other'].map(k=>`<option ${(tx?.paymentMethod||state.defaultPayment||'UPI')===k?'selected':''}>${k}</option>`).join('')}</select></div><div class="field full"><label for="notes">Notes (optional)</label><textarea id="notes" maxlength="250" placeholder="Add a note">${esc(tx?.notes||'')}</textarea></div></div><div class="modal-actions"><button type="button" class="button-secondary" id="cancelModal">Cancel</button><button class="button-primary" type="submit">${tx?'Save changes':'Add transaction'}</button></div></form></div>`;const close=()=>document.getElementById('modalRoot').innerHTML='';document.getElementById('closeModal').onclick=close;document.getElementById('cancelModal').onclick=close;document.getElementById('backdrop').onclick=e=>{if(e.target.id==='backdrop')close()};document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{draftType=b.dataset.kind;document.querySelectorAll('[data-kind]').forEach(k=>k.classList.toggle('selected',k.dataset.kind===draftType));const category=document.getElementById('category'),previous=category.value,allowed=Object.keys(categories).filter(k=>draftType==='expense'?!['Salary','Freelance','Business','Investment','Gift'].includes(k):['Salary','Freelance','Business','Investment','Gift','Other'].includes(k));category.innerHTML=allowed.map(k=>'<option>'+k+'</option>').join('');category.value=allowed.includes(previous)?previous:allowed[0]});document.getElementById('txForm').onsubmit=e=>{e.preventDefault();let x={id:tx?.id||crypto.randomUUID(),type:draftType,amount:Number(document.getElementById('amount').value),category:document.getElementById('category').value,description:document.getElementById('description').value.trim(),date:document.getElementById('date').value,paymentMethod:document.getElementById('payment').value,notes:document.getElementById('notes').value.trim(),createdAt:tx?.createdAt||Date.now()};if(!(x.amount>0)||!x.description||!x.date)return toast('Add a positive amount, description, and date.');let duplicate=state.transactions.some(q=>q.id!==x.id&&q.date===x.date&&q.amount===x.amount&&q.description.toLowerCase()===x.description.toLowerCase());if(duplicate&&!confirm('A transaction with the same date, amount, and description already exists. Add it anyway?'))return;if(tx)state.transactions=state.transactions.map(q=>q.id===tx.id?x:q);else state.transactions.push(x);save();close();render();toast(tx?'Transaction updated':'Transaction added')};document.getElementById('amount').focus()}
  function removeTx(id){let x=state.transactions.find(q=>q.id===id);if(!x)return;if(!confirm(`Delete “${x.description}”?`))return;state.transactions=state.transactions.filter(q=>q.id!==id);save();render();toast('Transaction removed')}
  function budgetModal(key){let isNew=key==='new',current=isNew?'':state.budgets[key]||'';let cat=key;document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" id="backdrop"><form class="modal" id="budgetForm"><div class="modal-head"><h2>${isNew?'Add category budget':'Set a budget'}</h2><button type="button" class="modal-close" id="closeModal">×</button></div><div class="form-grid"><div class="field full"><label for="budgetCategory">Category</label><select id="budgetCategory" ${isNew?'':'disabled'}>${(isNew?Object.keys(categories).filter(c=>!['Salary','Freelance','Business','Investment','Gift'].includes(c)):['total',key]).map(c=>`<option ${c===cat?'selected':''} value="${c}">${c==='total'?'Overall monthly limit':c}</option>`).join('')}</select></div><div class="field full"><label for="budgetAmount">Monthly amount (₹)</label><input id="budgetAmount" type="number" min="0" step="1" required value="${current}" placeholder="e.g. 10000"></div></div><div class="modal-actions"><button type="button" class="button-secondary" id="cancelModal">Cancel</button><button class="button-primary">Save budget</button></div></form></div>`;const close=()=>document.getElementById('modalRoot').innerHTML='';document.getElementById('closeModal').onclick=document.getElementById('cancelModal').onclick=close;document.getElementById('budgetForm').onsubmit=e=>{e.preventDefault();let c=document.getElementById('budgetCategory').value;state.budgets[c]=Number(document.getElementById('budgetAmount').value);save();close();render();toast('Budget saved')}}
  function reportItems(){let period=document.getElementById('reportPeriod').value,all=state.transactions;if(period==='selected')return all.filter(x=>x.date.slice(0,7)===picked());if(period==='previous'){let d=new Date(`${picked()}-01T12:00:00`);d.setMonth(d.getMonth()-1);return all.filter(x=>x.date.slice(0,7)===monthKey(d))}if(period==='year'){let y=document.getElementById('reportYear').value;return all.filter(x=>x.date.startsWith(y+'-'))}let a=document.getElementById('dateStart').value,b=document.getElementById('dateEnd').value;if(!a||!b||a>b)throw Error('Choose a valid start and end date.');return all.filter(x=>x.date>=a&&x.date<=b)}
  function updateReportCount(){let el=document.getElementById('reportCount');if(!el)return;try{let xs=reportItems();el.textContent=`${xs.length} transactions in selected range`}catch{el.textContent='Choose a valid date range'}}
